import React, { useState, useEffect } from 'react';
import { ShoppingCart, Search, X, Plus, Minus, Check } from 'lucide-react';

const AirtableStore = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [cart, setCart] = useState([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [showCheckout, setShowCheckout] = useState(false);
  const [orderComplete, setOrderComplete] = useState(false);
  const [checkoutData, setCheckoutData] = useState({
    name: '',
    email: '',
    address: ''
  });

  // ⚠️ IMPORTANT: Replace these with your actual Airtable credentials
  const AIRTABLE_API_KEY = 'patBxMl5uxbqMh90l.d0fa8c39cd2baed95b4d5f47cfa963e3374a2fbe8999edc690dc7a35bc6d8feb';
  const AIRTABLE_BASE_ID = 'appRMrTPEDmjy6Zka';
  const AIRTABLE_TABLE_NAME = 'Inventory';

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      const response = await fetch(
        `https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/${AIRTABLE_TABLE_NAME}`,
        {
          headers: {
            Authorization: `Bearer ${AIRTABLE_API_KEY}`,
          },
        }
      );

      if (!response.ok) {
        throw new Error('Failed to fetch products');
      }

      const data = await response.json();

      const formattedProducts = data.records.map(record => ({
        id: record.id,
        name: record.fields.Name || record.fields.name || 'Unnamed Product',
        price: parseFloat(record.fields.Price || record.fields.price || 0),
        description: record.fields.Description || record.fields.description || '',
        image: record.fields.Image?.[0]?.url || record.fields.image?.[0]?.url || 'https://via.placeholder.com/400x400?text=No+Image',
        category: record.fields.Category || record.fields.category || 'Uncategorized',
      }));

      setProducts(formattedProducts);
      setLoading(false);
    } catch (err) {
      setError(err.message);
      setLoading(false);
    }
  };

  const addToCart = (product) => {
    setCart(prevCart => {
      const existingItem = prevCart.find(item => item.id === product.id);
      if (existingItem) {
        return prevCart.map(item =>
          item.id === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...prevCart, { ...product, quantity: 1 }];
    });
  };

  const updateQuantity = (productId, change) => {
    setCart(prevCart => {
      return prevCart.map(item => {
        if (item.id === productId) {
          const newQuantity = item.quantity + change;
          return newQuantity > 0 ? { ...item, quantity: newQuantity } : item;
        }
        return item;
      }).filter(item => item.quantity > 0);
    });
  };

  const removeFromCart = (productId) => {
    setCart(prevCart => prevCart.filter(item => item.id !== productId));
  };

  const getTotalPrice = () => {
    return cart.reduce((total, item) => total + (item.price * item.quantity), 0).toFixed(2);
  };

  const getTotalItems = () => {
    return cart.reduce((total, item) => total + item.quantity, 0);
  };

  const filteredProducts = products.filter(product =>
    product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    product.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
    product.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleCheckout = () => {
    setShowCheckout(true);
  };

  const completeOrder = () => {
    if (checkoutData.name && checkoutData.email && checkoutData.address) {
      setOrderComplete(true);
      setTimeout(() => {
        setCart([]);
        setShowCheckout(false);
        setOrderComplete(false);
        setIsCartOpen(false);
        setCheckoutData({ name: '', email: '', address: '' });
      }, 3000);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-orange-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-4 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-700 text-lg font-medium">Loading products...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-red-50 to-orange-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl p-8 max-w-md border-4 border-red-200">
          <div className="text-red-500 text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-gray-800 mb-2">Configuration Error</h2>
          <p className="text-gray-600 mb-4">{error}</p>
          <p className="text-sm text-gray-500">Please update your Airtable credentials in the code.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-orange-50">
      {/* Header */}
      <header className="bg-white shadow-lg sticky top-0 z-40 border-b-4 border-yellow-400">
        <div className="max-w-7xl mx-auto px-4 py-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <img 
                src="/images/logo.png" 
                alt="UnrealPrices Logo" 
                className="h-16 w-16 object-contain"
                onError={(e) => {
                  e.target.style.display = 'none';
                  e.target.nextSibling.style.display = 'flex';
                }}
              />
              <div className="flex items-center space-x-3" style={{display: 'none'}}>
                <div className="bg-gradient-to-br from-blue-600 to-blue-700 p-3 rounded-full shadow-lg">
                  <ShoppingCart className="text-white" size={28} />
                </div>
                <h1 className="text-2xl font-bold text-gray-800">
                  Unreal<span className="text-blue-600">Prices</span>
                </h1>
              </div>
            </div>

            <button
              onClick={() => setIsCartOpen(true)}
              className="relative bg-gradient-to-r from-blue-600 to-blue-700 text-white px-6 py-3 rounded-full font-bold shadow-lg hover:shadow-xl hover:scale-105 transform transition-all duration-200 border-2 border-yellow-400"
            >
              <ShoppingCart className="inline mr-2" size={20} />
              Cart
              {getTotalItems() > 0 && (
                <span className="absolute -top-2 -right-2 bg-orange-500 text-white text-xs font-bold rounded-full h-7 w-7 flex items-center justify-center animate-bounce shadow-lg border-2 border-white">
                  {getTotalItems()}
                </span>
              )}
            </button>
          </div>
        </div>
      </header>

      {/* Search Bar */}
      <div className="max-w-7xl mx-auto px-4 py-8 sm:px-6 lg:px-8">
        <div className="relative max-w-2xl mx-auto">
          <Search className="absolute left-5 top-1/2 transform -translate-y-1/2 text-blue-400" size={22} />
          <input
            type="text"
            placeholder="Search for amazing deals..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-14 pr-4 py-4 rounded-full border-3 border-blue-200 focus:border-blue-500 focus:outline-none shadow-md hover:shadow-lg transition-all duration-200 text-lg"
          />
        </div>
      </div>

      {/* Products Grid */}
      <main className="max-w-7xl mx-auto px-4 pb-16 sm:px-6 lg:px-8">
        {filteredProducts.length === 0 ? (
          <div className="text-center py-16">
            <p className="text-gray-500 text-xl">No products found</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredProducts.map(product => (
              <div
                key={product.id}
                className="bg-white rounded-3xl shadow-xl overflow-hidden hover:shadow-2xl transform hover:-translate-y-3 transition-all duration-300 border-4 border-transparent hover:border-yellow-400"
              >
                <div className="relative h-64 bg-gradient-to-br from-blue-50 to-orange-50 overflow-hidden">
                  <img
                    src={product.image}
                    alt={product.name}
                    className="w-full h-full object-cover hover:scale-110 transition-transform duration-500"
                  />
                  <div className="absolute top-4 right-4 bg-blue-600 text-white px-4 py-2 rounded-full text-sm font-bold shadow-lg border-2 border-yellow-400">
                    {product.category}
                  </div>
                </div>

                <div className="p-6">
                  <h3 className="text-xl font-bold text-gray-800 mb-2">{product.name}</h3>
                  <p className="text-gray-600 text-sm mb-4 line-clamp-2">{product.description}</p>

                  <div className="flex items-center justify-between">
                    <div>
                      <div className="text-xs text-gray-500 font-semibold mb-1">ONLY</div>
                      <span className="text-3xl font-black text-blue-700">
                        ${product.price.toFixed(2)}
                      </span>
                    </div>
                    <button
                      onClick={() => addToCart(product)}
                      className="bg-gradient-to-r from-orange-500 to-orange-600 text-white px-6 py-3 rounded-full font-bold shadow-lg hover:shadow-xl hover:scale-105 transform transition-all duration-200 border-2 border-yellow-400"
                    >
                      Add to Cart
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>

      {/* Cart Sidebar */}
      {isCartOpen && (
        <div className="fixed inset-0 z-50 overflow-hidden">
          <div className="absolute inset-0 bg-black bg-opacity-60" onClick={() => setIsCartOpen(false)}></div>

          <div className="absolute right-0 top-0 h-full w-full max-w-md bg-white shadow-2xl transform transition-transform duration-300">
            <div className="flex flex-col h-full">
              {/* Cart Header */}
              <div className="bg-gradient-to-r from-blue-600 to-blue-700 text-white p-6 flex items-center justify-between border-b-4 border-yellow-400">
                <div>
                  <h2 className="text-2xl font-bold">Your Cart</h2>
                  <p className="text-blue-100 text-sm">{getTotalItems()} items</p>
                </div>
                <button
                  onClick={() => setIsCartOpen(false)}
                  className="hover:bg-white hover:bg-opacity-20 rounded-full p-2 transition-all duration-200"
                >
                  <X size={28} />
                </button>
              </div>

              {/* Cart Items */}
              <div className="flex-1 overflow-y-auto p-6 bg-gradient-to-br from-blue-50 to-orange-50">
                {cart.length === 0 ? (
                  <div className="text-center py-16">
                    <ShoppingCart className="mx-auto text-gray-300 mb-4" size={64} />
                    <p className="text-gray-500 text-lg font-medium">Your cart is empty</p>
                    <p className="text-gray-400 text-sm mt-2">Add some unreal deals!</p>
                  </div>
                ) : showCheckout ? (
                  orderComplete ? (
                    <div className="text-center py-16">
                      <div className="bg-green-100 rounded-full p-6 inline-block mb-4 border-4 border-green-300">
                        <Check className="text-green-600" size={64} />
                      </div>
                      <h3 className="text-2xl font-bold text-gray-800 mb-2">Order Complete!</h3>
                      <p className="text-gray-600">Thank you for shopping with us!</p>
                    </div>
                  ) : (
                    <div className="space-y-4">
                      <h3 className="text-xl font-bold mb-4 text-gray-800">Checkout Information</h3>

                      <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2">Full Name</label>
                        <input
                          type="text"
                          value={checkoutData.name}
                          onChange={(e) => setCheckoutData({...checkoutData, name: e.target.value})}
                          className="w-full px-4 py-3 border-2 border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                        />
                      </div>

                      <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2">Email</label>
                        <input
                          type="email"
                          value={checkoutData.email}
                          onChange={(e) => setCheckoutData({...checkoutData, email: e.target.value})}
                          className="w-full px-4 py-3 border-2 border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                        />
                      </div>

                      <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2">Shipping Address</label>
                        <textarea
                          rows="3"
                          value={checkoutData.address}
                          onChange={(e) => setCheckoutData({...checkoutData, address: e.target.value})}
                          className="w-full px-4 py-3 border-2 border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                        ></textarea>
                      </div>

                      <button
                        onClick={completeOrder}
                        className="w-full bg-gradient-to-r from-green-500 to-green-600 text-white py-4 rounded-full font-bold text-lg shadow-lg hover:shadow-xl hover:scale-105 transform transition-all duration-200 border-2 border-yellow-400"
                      >
                        Complete Order - ${getTotalPrice()}
                      </button>

                      <button
                        onClick={() => setShowCheckout(false)}
                        className="w-full bg-gray-200 text-gray-700 py-3 rounded-full font-bold hover:bg-gray-300 transition-all duration-200"
                      >
                        Back to Cart
                      </button>
                    </div>
                  )
                ) : (
                  <div className="space-y-4">
                    {cart.map(item => (
                      <div key={item.id} className="bg-white rounded-2xl p-4 flex items-center space-x-4 shadow-md border-2 border-blue-100">
                        <img
                          src={item.image}
                          alt={item.name}
                          className="w-20 h-20 object-cover rounded-xl"
                        />

                        <div className="flex-1">
                          <h4 className="font-bold text-gray-800">{item.name}</h4>
                          <p className="text-blue-600 font-black text-lg">${item.price.toFixed(2)}</p>
                        </div>

                        <div className="flex items-center space-x-2 bg-blue-50 rounded-full px-3 py-1">
                          <button
                            onClick={() => updateQuantity(item.id, -1)}
                            className="bg-white border-2 border-blue-300 rounded-full p-1 hover:bg-blue-100"
                          >
                            <Minus size={16} />
                          </button>
                          <span className="font-bold w-8 text-center text-blue-700">{item.quantity}</span>
                          <button
                            onClick={() => updateQuantity(item.id, 1)}
                            className="bg-white border-2 border-blue-300 rounded-full p-1 hover:bg-blue-100"
                          >
                            <Plus size={16} />
                          </button>
                        </div>

                        <button
                          onClick={() => removeFromCart(item.id)}
                          className="text-red-500 hover:text-red-700 hover:bg-red-50 rounded-full p-2"
                        >
                          <X size={20} />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {/* Cart Footer */}
              {cart.length > 0 && !showCheckout && (
                <div className="border-t-4 border-yellow-400 p-6 space-y-4 bg-white">
                  <div className="flex justify-between items-center text-2xl font-black">
                    <span className="text-gray-700">Total:</span>
                    <span className="text-blue-700">
                      ${getTotalPrice()}
                    </span>
                  </div>

                  <button
                    onClick={handleCheckout}
                    className="w-full bg-gradient-to-r from-orange-500 to-orange-600 text-white py-4 rounded-full font-bold text-lg shadow-lg hover:shadow-xl hover:scale-105 transform transition-all duration-200 border-2 border-yellow-400"
                  >
                    Proceed to Checkout
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AirtableStore;
